<?php
namespace App\Services; use App\Data\OrderData; use App\Enums\OrderStatus; use App\Events\OrderAssigned; use App\Events\ProgressUpdated; use App\Models\{Order, User}; use App\Repositories\OrderRepository; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class OrderService { public function __construct(private readonly OrderRepository $orders) {} public function create(OrderData $data): Order { return DB::transaction(fn()=> $this->orders->create(['order_code'=>'EEE-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'customer_id'=>$data->customerId,'worker_id'=>$data->workerId,'title'=>$data->title,'description'=>$data->description,'deadline'=>$data->deadline,'priority'=>$data->priority,'status'=>$data->workerId ? OrderStatus::Assigned : OrderStatus::WaitingPayment,'total_price'=>$data->totalPrice,'worker_fee'=>$data->workerFee])); } public function assignWorker(Order $order, User $worker): Order { return DB::transaction(function() use ($order,$worker){ $order->update(['worker_id'=>$worker->id,'status'=>OrderStatus::Assigned]); event(new OrderAssigned($order)); return $order->refresh(); }); } public function recordProgress(Order $order, User $actor, int $percentage, ?string $note, ?string $fileUrl = null): Order { return DB::transaction(function() use ($order,$actor,$percentage,$note,$fileUrl){ $order->progressUpdates()->create(['progress_percentage'=>$percentage,'note'=>$note,'file_url'=>$fileUrl,'created_by'=>$actor->id]); if ($percentage >= 100) { $order->update(['status'=>OrderStatus::Completed,'completed_at'=>now()]); } elseif ($order->status !== OrderStatus::Revision) { $order->update(['status'=>OrderStatus::InProgress]); } event(new ProgressUpdated($order, $percentage)); return $order->refresh(); }); } public function requestRevision(Order $order): Order { $order->increment('revision_count'); $order->update(['status'=>OrderStatus::Revision]); return $order->refresh(); } }
